input.command:
$dirs = @(
  "C:\Users\Administrator\Desktop\docuverse-kanzheli-main",
  "C:\Users\Administrator\Desktop\docuverse-frontend-lab",
  "C:\Users\Administrator\Desktop\docuverse-qrs",
  "C:\Users\Administrator\Desktop\docuverse-no-peek-lab"
); foreach ($d in $dirs) {
  Write-Host "==== $d ===="
  if (Test-Path "$d\.git") { Write-Host "HAS .git" } else { Write-Host "no .git" }
  if (Test-Path "$d\.tools") { Write-Host "HAS .tools"; Get-ChildItem "$d\.tools" -Recurse -Filter "*.exe" -ErrorAction SilentlyContinue | Select-Object -First 30 FullName } else { Write-Host "no .tools" }
  if (Test-Path "$d\私有库.txt") { Get-Content "$d\私有库.txt" -ErrorAction SilentlyContinue }
}
